q(17,'d - Green, 33','Split 0xFF202104 into bytes: alpha = FF, red = 20, green = 21, blue = 04. Shifting right by 8 moves the green byte to the lowest position; AND with 0xFF keeps just that byte. Hexadecimal 21 is decimal 2 x 16 + 1 = 33.')
code('0xFF202104u >> 8       = 0x00FF2021\n0x00FF2021 & 0xFFu     = 0x00000021\n0x21                  = 33')
